(()=>{'use strict';
const $=id=>document.getElementById(id),STORE='jigong-calendar-v1';
const today=new Date();today.setHours(12,0,0,0);let shown=new Date(today),chosen=new Date(today),choice='work',toastTimer,rangeVisible=60;
const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fromKey=k=>{const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d,12)};
const plus=(d,n)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+n,12);
const weekday=d=>['日','一','二','三','四','五','六'][d.getDay()];
const dateLabel=d=>`${d.getMonth()+1}月${d.getDate()}日 星期${weekday(d)}`;
const money=n=>'¥'+Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db={rate:20,records:{},period:null,range:null};try{const old=JSON.parse(localStorage.getItem(STORE));if(old&&typeof old==='object'&&old.records&&typeof old.records==='object'&&Number.isFinite(Number(old.rate)))db={rate:Number(old.rate),records:old.records,period:normalizePeriod(old.period),range:validRange(old.range)?old.range:null}}catch{}
function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function backupData(){return JSON.stringify({version:3,rate:db.rate,records:db.records,period:db.period,range:db.range},null,2)}
function syncNativeBackup(){try{window.AndroidBridge?.syncBackup(backupData())}catch{}}
function save(){try{localStorage.setItem(STORE,JSON.stringify(db));syncNativeBackup();return true}catch{notify('保存失败，请检查浏览器存储空间');return false}}
function minute(t){const [h,m]=String(t).split(':').map(Number);return h*60+m}
function segmentsOf(r){return Array.isArray(r?.segments)&&r.segments.length?r.segments:[{start:r?.start,end:r?.end}]}
function spanMinutes(s){let span=minute(s.end)-minute(s.start);if(span<0)span+=1440;return span}
function duration(r){if(!r||r.status!=='work')return 0;return Math.max(0,segmentsOf(r).reduce((n,s)=>n+spanMinutes(s),0)-Number(r.breakMinutes||0))/60}
function scheduleText(r){return segmentsOf(r).map(s=>`${s.start}–${s.end}`).join('、')}
function cloneRecord(r){return JSON.parse(JSON.stringify(r))}
function validPeriod(p){return !!p&&Number.isInteger(p.startDay)&&Number.isInteger(p.endDay)&&p.startDay>=1&&p.endDay<=31&&p.startDay<=p.endDay&&!(p.startDay===1&&p.endDay>=28)}
function normalizePeriod(p){if(validPeriod(p))return {startDay:p.startDay,endDay:p.endDay};if(p&&Number.isInteger(p.first)&&Number.isInteger(p.second)&&p.first>=1&&p.second<=28&&p.first<p.second)return {startDay:p.first,endDay:p.second-1};return null}
function validDateKey(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&key(fromKey(value))===value}
function validRange(value){return !!value&&validDateKey(value.start)&&validDateKey(value.end)&&value.start<=value.end}
function monthRange(date){return {start:key(new Date(date.getFullYear(),date.getMonth(),1,12)),end:key(new Date(date.getFullYear(),date.getMonth()+1,0,12))}}
function recordsInRange(records,range){return Object.entries(records).filter(([k,r])=>k>=range.start&&k<=range.end&&r?.status==='work')}
const income=r=>duration(r)*Number(r.rate||0);
function hText(n){const minutes=Math.round(n*60),h=Math.floor(minutes/60),m=minutes%60;return m?`${h}小时${m}分`:`${h}小时`}
function compactHours(n){const value=Math.round(n*10)/10;return n>0&&value===0?'<0.1h':`${value}h`}
function monthRows(){const prefix=`${shown.getFullYear()}-${String(shown.getMonth()+1).padStart(2,'0')}-`;return Object.entries(db.records).filter(([k,r])=>k.startsWith(prefix)&&r?.status==='work')}
function render(){const rows=monthRows(),hrs=rows.reduce((n,[,r])=>n+duration(r),0),cash=rows.reduce((n,[,r])=>n+income(r),0);$('monthTitle').textContent=`${shown.getFullYear()}年${shown.getMonth()+1}月`;$('wageMonth').textContent=$('monthTitle').textContent;$('monthMoney').textContent=money(cash);$('monthHours').textContent=hText(hrs);$('monthDays').textContent=rows.length+'天';$('wageMoney').textContent=money(cash);$('wageHours').textContent=hText(hrs);$('rateText').textContent=`${money(db.rate)} / 小时`;renderCalendar();renderDay();renderWages(rows)}
function renderCalendar(){const cal=$('calendar');cal.innerHTML='';const y=shown.getFullYear(),m=shown.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate();for(let i=0;i<offset;i++){const blank=document.createElement('div');blank.className='day empty';cal.append(blank)}for(let n=1;n<=count;n++){const d=new Date(y,m,n,12),r=db.records[key(d)],b=document.createElement('button');b.type='button';b.className='day'+(r?' '+r.status:'')+(key(d)===key(today)?' today':'')+(key(d)===key(chosen)?' selected':'');b.setAttribute('aria-label',`${dateLabel(d)}，${r?(r.status==='rest'?'休息':hText(duration(r))+'，'+money(income(r))):'未记录'}`);b.innerHTML=`<span class="day-num">${n}</span>${r?`<span class="day-label">${r.status==='rest'?'休息':safe(compactHours(duration(r)))}</span>`:''}${r?.status==='work'?`<span class="day-money">${safe(money(income(r)))}</span>`:''}`;b.onclick=()=>{chosen=d;render();$('dayTitle').scrollIntoView({block:'nearest',behavior:'smooth'})};cal.append(b)}}
function renderDay(){const r=db.records[key(chosen)];$('dayTitle').textContent=dateLabel(chosen);$('dayBadge').textContent=!r?'未记录':r.status==='rest'?'休息':'已上班';$('dayDetail').innerHTML=!r?'这一天还没有记录。可以手动填写，也可以直接复制前一天。':r.status==='rest'?'这一天记为休息。':`<strong>${safe(scheduleText(r))}</strong>${Number(r.breakMinutes||0)?` · 额外休息${Number(r.breakMinutes)}分钟`:''}<br>工时 <strong>${safe(hText(duration(r)))}</strong> · 预计收入 <strong>${safe(money(income(r)))}</strong>`;$('editDay').textContent=r?'修改这一天':'记录这一天';$('copyMany').disabled=!r}
function renderRange(){const range=validRange(db.range)?db.range:monthRange(today);$('rangeStart').value=range.start;$('rangeEnd').value=range.end;const rows=recordsInRange(db.records,range).sort((a,b)=>b[0].localeCompare(a[0])),hours=rows.reduce((n,[,r])=>n+duration(r),0),cash=rows.reduce((n,[,r])=>n+income(r),0),start=fromKey(range.start),end=fromKey(range.end);$('rangeSummary').innerHTML=`<div class="range-dates">${start.getFullYear()}年${start.getMonth()+1}月${start.getDate()}日－${end.getFullYear()}年${end.getMonth()+1}月${end.getDate()}日</div><strong>${money(cash)}</strong><span>${rows.length}天上班 · ${hText(hours)}</span>`;const box=$('rangeDailyList');box.innerHTML='<div class="row"><strong>这段时间每天明细</strong></div>';for(const [k,r] of rows.slice(0,rangeVisible)){const d=fromKey(k);box.innerHTML+=`<div class="row"><div><strong>${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日</strong><small>${hText(duration(r))} · ${safe(scheduleText(r))}</small></div><div class="money">${money(income(r))}</div></div>`}if(!rows.length)box.innerHTML+='<div class="row"><small>这段时间没有上班记录。</small></div>';$('moreRange').hidden=rows.length<=rangeVisible;$('moreRange').textContent=`查看更多每天明细（已显示${Math.min(rows.length,rangeVisible)}／${rows.length}天）`}
function renderWages(rows){renderRange();const weeks=new Map();for(const [k,r] of rows){const d=fromKey(k),monday=plus(d,-((d.getDay()+6)%7)),wk=key(monday);if(!weeks.has(wk))weeks.set(wk,{hours:0,cash:0});const o=weeks.get(wk);o.hours+=duration(r);o.cash+=income(r)}const box=$('weeklyList');box.innerHTML='<div class="row"><strong>每周收入</strong></div>';for(const [k,v] of [...weeks].sort((a,b)=>a[0].localeCompare(b[0]))){const d=fromKey(k),end=plus(d,6);box.innerHTML+=`<div class="row"><div><strong>${d.getMonth()+1}月${d.getDate()}日－${end.getMonth()+1}月${end.getDate()}日</strong><small>${hText(v.hours)}</small></div><div class="money">${money(v.cash)}</div></div>`}if(!weeks.size)box.innerHTML+='<div class="row"><small>这个月还没有上班记录</small></div>';const daily=$('dailyList');daily.innerHTML='<div class="row"><strong>每天明细</strong></div>';for(const [k,r] of [...rows].sort((a,b)=>b[0].localeCompare(a[0]))){const d=fromKey(k);daily.innerHTML+=`<div class="row"><div><strong>${d.getMonth()+1}月${d.getDate()}日 星期${weekday(d)}</strong><small>${hText(duration(r))} · ${safe(scheduleText(r))}</small></div><div class="money">${money(income(r))}</div></div>`}if(!rows.length)daily.innerHTML+='<div class="row"><small>点日历上的日期，开始记工。</small></div>'}
function open(id){$(id).classList.add('open');document.body.style.overflow='hidden'}function close(id){$(id).classList.remove('open');document.body.style.overflow=''}
function mode(m){choice=m;$('workChoice').classList.toggle('active',m==='work');$('restChoice').classList.toggle('active',m==='rest');$('workFields').hidden=m==='rest'}
function addSegmentRow(segment={start:'',end:''}){const box=$('segmentsList'),index=box.children.length+1,row=document.createElement('div');row.className='segment-row';row.innerHTML=`<div class="segment-top"><strong>第 ${index} 段</strong><button type="button" class="remove-segment" aria-label="删除第 ${index} 段">删除</button></div><div class="two"><div><label>上班时间<input class="segment-start" type="time"></label></div><div><label>下班时间<input class="segment-end" type="time"></label></div></div>`;row.querySelector('.segment-start').value=segment.start||'';row.querySelector('.segment-end').value=segment.end||'';row.querySelectorAll('input').forEach(input=>input.addEventListener('input',preview));row.querySelector('.remove-segment').onclick=()=>{if(box.children.length===1){notify('至少保留一段时间');return}row.remove();[...box.children].forEach((item,i)=>{item.querySelector('.segment-top strong').textContent=`第 ${i+1} 段`;item.querySelector('.remove-segment').setAttribute('aria-label',`删除第 ${i+1} 段`)});preview()};box.append(row)}
function editorRecord(){const segments=[...$('segmentsList').children].map(row=>({start:row.querySelector('.segment-start').value,end:row.querySelector('.segment-end').value}));return {status:'work',segments,start:segments[0]?.start,end:segments.at(-1)?.end,breakMinutes:Number($('breakMinutes').value),rate:Number($('dayRate').value)}}
function openEditor(){const r=db.records[key(chosen)];$('editTitle').textContent=dateLabel(chosen);mode(r?.status||'work');$('segmentsList').innerHTML='';(r?.status==='work'?segmentsOf(r):[{start:'09:00',end:'18:00'}]).forEach(addSegmentRow);$('breakMinutes').value=r?.breakMinutes??0;$('dayRate').value=r?.rate??db.rate;$('deleteDay').hidden=!r;preview();open('dayOverlay')}
function preview(){const r=editorRecord(),err=invalid(r);$('preview').textContent=err?err:`预计工时 ${hText(duration(r))}，预计收入 ${money(income(r))}`}
function invalid(r){const segments=segmentsOf(r),time=/^(?:[01]\d|2[0-3]):[0-5]\d$/;if(!segments.length||segments.length>8)return '请填写 1～8 段上班时间';let total=0,previousEnd=-1;for(const s of segments){if(!time.test(s.start)||!time.test(s.end)||s.start===s.end)return '请填写不同的上班和下班时间';const start=minute(s.start),end=minute(s.end);if(segments.length>1&&(end<=start||start<previousEnd))return '多段时间请按当天先后填写，且不能重叠';total+=spanMinutes(s);previousEnd=end}if(!Number.isInteger(r.breakMinutes)||r.breakMinutes<0||r.breakMinutes>=total)return '额外休息时间需少于上班时段';if(!Number.isFinite(r.rate)||r.rate<0||r.rate>100000)return '请填写正确的工价';return ''}
function saveDay(){const r=choice==='rest'?{status:'rest'}:editorRecord();if(choice==='work'){if($('breakMinutes').value===''||$('dayRate').value===''){notify('请填写额外休息时间和工价');return}const err=invalid(r);if(err){notify(err);return}}db.records[key(chosen)]=r;if(save()){close('dayOverlay');render();notify('已保存')}}
function copyYesterday(){const d=plus(chosen,-1),r=db.records[key(d)];if(!r){notify('前一天没有记录，请先手动填写');return}if(db.records[key(chosen)]&&!confirm(`${dateLabel(chosen)}已有记录，确定用前一天的记录覆盖吗？`))return;db.records[key(chosen)]=cloneRecord(r);if(save()){render();notify(`已复制${d.getMonth()+1}月${d.getDate()}日的记录`)}}
function copyMany(){const r=db.records[key(chosen)];if(!r){notify('请先记录所选日期');return}$('copyInfo').textContent=`把 ${dateLabel(chosen)} 的${r.status==='rest'?'休息':'工时'}复制到哪些日期？`;const box=$('copyDates');box.innerHTML='';for(let i=1;i<=14;i++){const d=plus(chosen,i),k=key(d),lab=document.createElement('label');lab.className='check';const input=document.createElement('input');input.type='checkbox';input.value=k;const span=document.createElement('span');span.textContent=`${d.getMonth()+1}月${d.getDate()}日 ${weekday(d)}${db.records[k]?' · 已有':''}`;lab.append(input,span);box.append(lab)}open('copyOverlay')}
function confirmCopy(){const dates=[...$('copyDates').querySelectorAll('input:checked')].map(x=>x.value);if(!dates.length){notify('请先选择日期');return}const occupied=dates.filter(k=>db.records[k]);if(occupied.length&&!confirm(`选中的日期里有${occupied.length}天已有记录。确定覆盖吗？`))return;const r=db.records[key(chosen)];dates.forEach(k=>db.records[k]=cloneRecord(r));if(save()){close('copyOverlay');render();notify(`已复制到${dates.length}天`)}}
function copyWeek(){const monday=plus(chosen,-((chosen.getDay()+6)%7)),pairs=Array.from({length:7},(_,i)=>({source:key(plus(monday,i)),target:key(plus(monday,i+7))})).filter(x=>db.records[x.source]);if(!pairs.length){notify('本周没有可复制的记录');return}const occupied=pairs.filter(x=>db.records[x.target]).length;if(!confirm(`把本周${pairs.length}天记录复制到下周${occupied?`，其中${occupied}天已有记录会被覆盖`:''}。确定吗？`))return;const copies=pairs.map(x=>({target:x.target,record:cloneRecord(db.records[x.source])}));copies.forEach(x=>db.records[x.target]=x.record);if(save()){render();notify('已复制到下周')}}
function download(name,contents,type){if(window.AndroidBridge){window.AndroidBridge.saveText(name,'\ufeff'+contents,type);return}const blob=new Blob(['\ufeff',contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const lines=[['日期','状态','上班时段','额外休息分钟','工时小时','工价元每小时','预计收入元'].join(',')];for(const [k,r] of Object.entries(db.records).sort((a,b)=>a[0].localeCompare(b[0])))lines.push([k,r.status==='rest'?'休息':'上班',r.status==='work'?scheduleText(r):'',r.breakMinutes??'',r.status==='work'?duration(r).toFixed(2):'',r.rate??'',r.status==='work'?income(r).toFixed(2):''].join(','));download('记工日历-工时表.csv',lines.join('\r\n'),'text/csv;charset=utf-8')}
function showSelectedRange(){const range={start:$('rangeStart').value,end:$('rangeEnd').value};if(!validRange(range)){notify('请选正确的开始和结束日期，结束不能早于开始');return}db.range=range;if(save()){rangeVisible=60;renderRange();notify('已更新这段时间的工资')}}
function refreshAutoBackupStatus(){if(!window.AndroidBridge?.getBackupStatus)return;$('autoBackupCard').hidden=false;try{$('autoBackupStatus').textContent=window.AndroidBridge.getBackupStatus()}catch{$('autoBackupStatus').textContent='自动备份状态暂时无法读取。'}}
function shift(n){shown=new Date(shown.getFullYear(),shown.getMonth()+n,1,12);render()}
$('prevMonth').onclick=$('wagePrev').onclick=()=>shift(-1);$('nextMonth').onclick=$('wageNext').onclick=()=>shift(1);$('todayBtn').onclick=()=>{shown=new Date(today);chosen=new Date(today);document.querySelector('[data-page="calendarPage"]').click();render()};$('editDay').onclick=openEditor;$('workChoice').onclick=()=>mode('work');$('restChoice').onclick=()=>mode('rest');$('addSegment').onclick=()=>{if($('segmentsList').children.length>=8){notify('一天最多记录 8 段时间');return}addSegmentRow();preview()};['breakMinutes','dayRate'].forEach(id=>$(id).addEventListener('input',preview));$('saveDay').onclick=saveDay;$('deleteDay').onclick=()=>{if(!confirm(`确定删除 ${dateLabel(chosen)} 的记录吗？`))return;delete db.records[key(chosen)];if(save()){close('dayOverlay');render();notify('已删除')}};$('copyYesterday').onclick=copyYesterday;$('copyMany').onclick=copyMany;$('confirmCopy').onclick=confirmCopy;$('copyWeek').onclick=copyWeek;$('showRange').onclick=showSelectedRange;$('moreRange').onclick=()=>{rangeVisible+=60;renderRange()};$('rangeThisMonth').onclick=()=>{db.range=monthRange(today);if(save()){rangeVisible=60;renderRange()}};$('rangeLastMonth').onclick=()=>{db.range=monthRange(new Date(today.getFullYear(),today.getMonth()-1,1,12));if(save()){rangeVisible=60;renderRange()}};$('chooseBackupFolder').onclick=()=>{try{window.AndroidBridge?.chooseBackupFolder()}catch{notify('无法打开文件夹选择界面')}};window.onAutoBackupChanged=refreshAutoBackupStatus;
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)close(el.id)}));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay.open').forEach(el=>close(el.id))});document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));window.scrollTo(0,0)});
$('changeRate').onclick=()=>{$('newRate').value=db.rate;open('rateOverlay')};$('saveRate').onclick=()=>{const v=$('newRate').value,n=Number(v);if(v===''||!Number.isFinite(n)||n<0||n>100000){notify('请填写正确的工价');return}db.rate=n;if(save()){close('rateOverlay');render();notify('工价已更新')}};$('exportCsv').onclick=csv;$('exportBackup').onclick=()=>download('记工日历-完整备份.json',backupData(),'application/json;charset=utf-8');$('importBackup').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(![1,2,3].includes(obj?.version)||!obj.records||typeof obj.records!=='object'||!Number.isFinite(Number(obj.rate)))throw Error();if(!confirm('导入备份会替换当前手机里的所有记录，确定继续吗？'))return;const records={};for(const [k,r] of Object.entries(obj.records)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k))continue;if(r?.status==='rest')records[k]={status:'rest'};else if(r?.status==='work'){const v={status:'work',start:r.start,end:r.end,segments:Array.isArray(r.segments)?r.segments.map(s=>({start:s.start,end:s.end})):undefined,breakMinutes:Number(r.breakMinutes),rate:Number(r.rate)};if(!invalid(v))records[k]=v}}db={rate:Number(obj.rate),records,period:normalizePeriod(obj.period),range:validRange(obj.range)?obj.range:null};if(save()){render();notify(`已导入${Object.keys(records).length}天记录`)}}catch{notify('备份文件无法读取')}finally{e.target.value=''}};
render();syncNativeBackup();refreshAutoBackupStatus();if(!window.AndroidBridge&&'serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
})();

